mod functional;
mod simple;
mod tables;
mod utils;

use crate::glu::{TestCase, TestCaseGroup};
use crate::glw;

/// `CopyImageTests::addFunctionalTest`
fn add_functional_test(group: &mut TestCaseGroup) {
    for src_target in tables::VALID_TARGETS {
        // Only the targets the default `COPY_IMAGE_FUNCTIONAL_TEST_ENABLE_ALL_TARGETS == 0` leaves in.
        if matches!(
            src_target,
            glw::GL_TEXTURE_1D
                | glw::GL_TEXTURE_1D_ARRAY
                | glw::GL_TEXTURE_2D
                | glw::GL_TEXTURE_CUBE_MAP
                | glw::GL_TEXTURE_CUBE_MAP_ARRAY
        ) {
            continue;
        }

        for dst_target in tables::VALID_TARGETS {
            if matches!(
                dst_target,
                glw::GL_TEXTURE_1D
                    | glw::GL_TEXTURE_1D_ARRAY
                    | glw::GL_TEXTURE_2D
                    | glw::GL_TEXTURE_CUBE_MAP
                    | glw::GL_TEXTURE_CUBE_MAP_ARRAY
            ) {
                continue;
            }

            // Skip render buffer as destination
            if dst_target == glw::GL_RENDERBUFFER {
                continue;
            }

            // Skip multisampled
            if utils::is_target_multisampled(src_target) || utils::is_target_multisampled(dst_target) {
                continue;
            }

            for src_format in tables::INTERNAL_FORMATS {
                if src_format == glw::GL_RGB9_E5 && src_target == glw::GL_RENDERBUFFER {
                    continue;
                }

                for dst_format in tables::INTERNAL_FORMATS {
                    // Skip not compatible formats
                    if !utils::are_formats_compatible(src_format, dst_format) {
                        continue;
                    }

                    group.add_child(Box::new(functional::FunctionalTest::new(
                        dst_format, dst_target, src_format, src_target,
                    )) as Box<dyn TestCase>);
                }
            }
        }
    }
}

/// `CopyImageTests::init`
pub fn create_tests() -> TestCaseGroup {
    let mut group = TestCaseGroup::new("copy_image");

    add_functional_test(&mut group);
    group.add_child(Box::new(simple::IncompleteTexTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::InvalidObjectTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::SmokeTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::InvalidTargetTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::TargetMismatchTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::IncompatibleFormatsTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::SamplesMismatchTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::IncompatibleFormatsCompressionTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::NonExistentMipMapTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::ExceedingBoundariesTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::InvalidAlignmentTest::new()) as Box<dyn TestCase>);
    group.add_child(Box::new(simple::IntegerTexTest) as Box<dyn TestCase>);
    group
}
